int h = result.getHeight();
int checkX = Math.max(0, w - insets - (watermarkSize / 2));
int checkY = Math.max(0, h - insets - (watermarkSize / 2));

int rgb = result.getRGB(checkX, checkY);
int rDiff = Math.abs(((rgb >> 16) & 0xFF) - ((expectedColor >> 16) & 0xFF));
int gDiff = Math.abs(((rgb >> 8) & 0xFF) - ((expectedColor >> 8) & 0xFF));
